    'helper.firstBuild': 'Erster Windows-Build: Setup + Launcher',
    'helper.firstBuildNote': 'BUILD-WINDOWS.bat erstellt jetzt beide Artefakte: ColonialHelperSetup.exe für die Erstinstallation und ColonialHelper.exe — den Launcher/Payload, den der bestehende Update-Kanal braucht. Verteilen Sie das Setup als Installer. Unten wird nur ColonialHelper.exe hochgeladen; laden Sie dort kein Setup hoch, sonst ersetzt es den Basis-Update-Launcher. Der Build läuft auf einem vertrauenswürdigen Windows-Rechner; beim Hochladen wird der Launcher in Teilen bis 4 MiB übertragen.',
